E.append((6029519,'چکن اور پالک اینچیلاداز',
'زیادہ سبزیاں کھانے کی کوشش کر رہے ہیں؟ یہ روزمرہ کی ڈش میں سبزیاں شامل کرنے کا ایک بہترین طریقہ ہے۔ وقت کم ہے؟ اپنے مقامی گروسری اسٹور سے پکا ہوا روٹی سیری چکن استعمال کریں۔',
'5','2 اینچیلاداز',
['1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے','12 اونس پکا ہوا چکن بریسٹ (ریشہ ریشہ کیا ہوا)','9 اونس منجمد پالک (کٹی ہوئی، پگھلائی ہوئی اور پانی نکالی ہوئی)','1 لہسن کی پھانک (قیمہ کی ہوئی)','1/2 چائے کا چمچ زیرہ','1 کھانے کا چمچ تازہ دھنیا','1/4 چائے کا چمچ کالی مرچ','3/4 کپ چیڈر پنیر (کم چکنائی والا، کدوکش کیا ہوا)','12 چھوٹے مکئی کے ٹورٹیلا (6 انچ، گرم کیے ہوئے)','3/4 کپ ڈبہ بند ہری اینچیلادا ساس'],
['اوون کو 350 ڈگری F پر پہلے سے گرم کریں۔ ایک بڑی دھاتی یا شیشے کی بیکنگ ڈش پر کوکنگ اسپرے کریں۔','ایک چھوٹے پیالے میں پالک، لہسن، زیرہ، دھنیا، مرچ اور چیڈر پنیر ملا لیں؛ ملانے کے لیے اچھی طرح مکس کریں۔ ریشہ ریشہ کیا ہوا چکن ڈالیں؛ ملانے کے لیے مکس کریں۔','1/4 کپ چکن-پالک کا مرکب ایک ٹورٹیلا میں ڈالیں۔ ٹورٹیلا کو لپیٹیں اور جوڑ والی طرف نیچے کر کے بیکنگ ڈش میں رکھیں۔ باقی 11 ٹورٹیلا کے لیے یہی عمل دہرائیں۔','اینچیلادا ساس ٹورٹیلا پر ڈالیں۔ 25 منٹ بیک کریں۔'],[]))
E.append((6030116,'کم کاربوہائیڈریٹ چکن اور توری کیسرول',
'یہ مزیدار کم کاربوہائیڈریٹ چکن اور توری کیسرول پکا ہوا چکن، تازہ توری اور مزیدار کریمی پن کو ملاتا ہے۔ بھرپور اور اطمینان بخش ذائقوں کے ساتھ، یہ ہفتے کے دن خاندان کے رات کے کھانے کے لیے ایک آسان انتخاب ہے۔ یہ ذیابیطس کے لیے موزوں ترکیب آپ کے خون میں گلوکوز (بلڈ شوگر) کے انتظام کے منصوبے سے سمجھوتہ کیے بغیر پنیر کے مزے کی آپ کی خواہش پوری کرے گی۔',
'6','1 ½ کپ',
['1 عدد مکھن کے ذائقے والا کوکنگ اسپرے (بیکنگ ڈش پر چکنائی لگانے کے لیے)','4 درمیانی توری (کوسا) (پتلی کٹی ہوئی)','1 چھوٹی پیاز (پتلی کٹی ہوئی)','3/4 کپ کم چکنائی والا موزاریلا پنیر (کدوکش کیا ہوا)','8 اونس بغیر ہڈی اور بغیر کھال کے چکن بریسٹ (پکا ہوا اور ریشہ ریشہ کیا ہوا)','1 کپ چکنائی سے پاک ہاف اینڈ ہاف','1/2 چائے کا چمچ پسا ہوا دھنیا','1/2 چائے کا چمچ نمک','1/4 چائے کا چمچ کالی مرچ','2 چائے کے چمچ زیتون کا تیل'],
['اپنے اوون کو 375 ڈگری F (190 ڈگری C) پر پہلے سے گرم کریں۔','9x13 کی بیکنگ ڈش پر کوکنگ اسپرے یا مکھن سے چکنائی لگائیں۔ ڈش کی تہہ میں کٹی ہوئی توری کی ایک تہہ لگائیں، ہلکا سا ایک دوسرے پر چڑھاتے ہوئے۔ توری پر کٹی ہوئی پیاز کا ایک حصہ چھڑکیں۔ پیاز پر کدوکش کیے ہوئے پنیر کا تھوڑا سا حصہ چھڑکیں۔ تہوں کو دہراتے رہیں جب تک تمام توری، پیاز اور آدھا پنیر استعمال نہ ہو جائے۔','پکا ہوا چکن تہہ در تہہ توری اور پنیر پر برابر چھڑکیں۔','ایک چھوٹے سوس پین میں درمیانی آنچ پر زیتون کا تیل ڈالیں۔ ہاف اینڈ ہاف، دھنیا، نمک اور مرچ ملا دیں۔ مرکب کو اس وقت تک گرم کریں جب تک وہ اچھی طرح گرم نہ ہو جائے۔','کریم کا مرکب تہہ در تہہ توری، پیاز، پنیر اور چکن پر برابر ڈالیں۔ باقی پنیر اوپر چھڑک دیں۔','بیکنگ ڈش کو ایلومینیم ورق سے ڈھانپیں اور پہلے سے گرم اوون میں 30 منٹ بیک کریں۔','ورق ہٹا دیں اور مزید 15–20 منٹ بیک کرتے رہیں، یا جب تک توری نرم نہ ہو جائے، چکن گرم نہ ہو جائے، اور پنیر پگھل کر سنہری نہ ہو جائے۔ پیش کرنے سے پہلے کیسرول کو چند منٹ ٹھہرنے دیں۔'],[]))
E.append((6030314,'بروکلی سلا مسٹرڈ ڈریسنگ کے ساتھ',
'ہماری شوخ بروکلی سلا کے ساتھ جس میں تیز مسٹرڈ ڈریسنگ ہے، اپنے سلاد کو اگلے درجے پر لے جائیں۔ بروکلی، رنگین سبزیوں اور کھٹی مسٹرڈ ڈریسنگ کا یہ خستہ اور تازگی بخش امتزاج ایک ذائقہ دار سائیڈ ڈش بناتا ہے۔',
'6','3/4 کپ',
['4 کپ بروکلی سلا','1/4 کپ لال پیاز (باریک کٹی ہوئی)','1/4 کپ کشمش (یا خشک کرین بیریاں)','1/4 کپ سورج مکھی کے بیج (بھنے ہوئے)','1/2 کپ سادہ بغیر چکنائی والا یونانی دہی','2 کھانے کے چمچ ڈیجون مسٹرڈ','1 کھانے کا چمچ ایپل سائیڈر سرکہ','1 کھانے کا چمچ بغیر میٹھے کا کثیر المقاصد سیرپ','1/4 چائے کا چمچ کوشر نمک','1/4 چائے کا چمچ کالی مرچ'],
['ایک بڑے پیالے میں بروکلی سلا مکس، باریک کٹی ہوئی لال پیاز، کشمش یا خشک کرین بیریاں، اور بھنے ہوئے سورج مکھی کے بیج ملا دیں۔','ایک چھوٹے پیالے میں یونانی دہی، ڈیجون مسٹرڈ، ایپل سائیڈر سرکہ، بغیر میٹھے کا کثیر المقاصد سیرپ، کوشر نمک اور کالی مرچ پھینٹ کر ملا لیں۔','ڈریسنگ سلا پر ڈالیں اور برابر لگانے کو یقینی بنانے کے لیے آہستگی سے ملا دیں۔'],[]))
E.append((6032146,'بیف اور شکر قندی کا اسٹیو',
'اگر آپ چاہیں تو اس ترکیب میں شکر قندی کی جگہ بٹرنٹ اسکواش استعمال کر سکتے ہیں۔ یہ اسٹیو روٹ ویجیٹیبل کیکس کے اوپر پیش کرنے پر بہت اچھا لگتا ہے۔',
'8','1 1/2 کپ-1.5',
['1 کھانے کا چمچ زیتون کا تیل','1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے','1 1/2 پاؤنڈ کم چکنائی والا بیف اسٹیو گوشت ((چک یا راؤنڈ))','1 درمیانی پیاز (چوکور کٹی ہوئی)','2 درمیانی گاجریں (1/2 انچ موٹے گول ٹکڑوں میں کٹی ہوئی)','2 اجوائن (سیلری) کی ڈنڈیاں (چوکور کٹی ہوئی)','2 1/2 کپ چکنائی سے پاک، کم سوڈیم والا بیف شوربہ','1/2 کپ آلو بخارا (پرونز) (چوکور کٹے ہوئے)','1 کپ گرم پانی','2 درمیانی (کل تقریباً 12 اونس) شکر قندی (چھلی ہوئی اور 1 انچ کے ٹکڑوں میں چوکور کٹی ہوئی)','1 1/2 چائے کا چمچ پسی ہوئی دار چینی','1 چائے کا چمچ کالی مرچ','1 چائے کا چمچ کوشر نمک','1/4 کپ کٹا ہوا تازہ پارسلے (اجمود)'],
['ایک بڑے سوپ کے برتن میں تیز آنچ پر زیتون کا تیل اور فراخ مقدار میں کوکنگ اسپرے ڈالیں۔ کھیپوں میں گوشت کو ہر طرف سے بھورا کریں۔ پین میں گوشت کو بہت زیادہ نہ بھریں ورنہ وہ بھورا نہیں ہوگا۔','گوشت کو پین سے نکال کر ایک طرف رکھ دیں۔ پیاز، گاجر اور اجوائن پین میں ڈالیں اور 4-5 منٹ ساٹے کریں۔','بیف شوربہ ڈالیں اور پین کی تہہ سے بھورے ٹکڑے کھرچ لیں۔ گوشت شامل کریں اور 1 گھنٹہ ہلکی آنچ پر پکائیں۔','جب گوشت ہلکی آنچ پر پک رہا ہو، آلو بخارے کو گرم پانی میں 20 منٹ بھگو دیں۔ آلو بخارے کا پانی نکال دیں، پانی بچا کر رکھیں اور آلو بخارے کو ایک طرف رکھ دیں۔','گوشت کے 1 گھنٹہ ہلکی آنچ پر پکنے کے بعد، پانی نکالے ہوئے آلو بخارے، شکر قندی، آلو بخارے کے پانی کا 1/2 کپ، دار چینی، پسی ہوئی کالی مرچ اور نمک ڈالیں۔ ڈھانپ کر 20 منٹ تک یا آلو کے نرم ہونے تک ہلکی آنچ پر ابال آنے دیں۔','کٹا ہوا پارسلے ملا دیں اور پیش کریں۔'],[]))
build(9,E)
